.intro{position:absolute;z-index:20;inset:0;display:flex;align-items:center;justify-content:center;background:linear-gradient(90deg,rgba(5,10,7,.96),rgba(8,13,9,.76) 55%,rgba(8,12,8,.35)),radial-gradient(ellipse at 70% 50%,#46523a 0,#1d271b 45%,#0a0e0a 80%)}
