    arm.position.set(side * .48, 4.55, 0); root.add(arm);
    const head = S(new THREE.Mesh(new THREE.BoxGeometry(.5, .13, .26), M.lampMetal));
    head.position.set(side * .92, 4.48, 0); root.add(head);
