/* ---------------- interaction ---------------- */
let near = null;
function findNear() {
  const p = playerWorld();
  let best = null, bd = 2.7;
  for (const it of world.interactables) {
    if (it.kind === 'loot' && !it.active) continue;
    if (it.kind === 'car' && !it.active) continue;
    const d = Math.hypot(it.wx - p.x, it.wz - p.z);
    if (d < bd) { bd = d; best = it; }
