    const old = corpses.shift();
    if (old && old.model) scene.remove(old.model.root);
  }
}
function hurt(n) {
  if (state.gameOver || state.mode !== 'play') return;
  player.hp = Math.max(0, player.hp - n);
  player.hurtT = .3;
