238: function updateHud() {
239:   ui.healthFill.style.width = clamp(player.hp, 0, 100) + '%';
240:   ui.staminaFill.style.width = clamp(player.st, 0, 100) + '%';
241:   ui.hungerFill.style.width = clamp(player.hunger, 0, 100) + '%';
242:   ui.healthNum.textContent = Math.round(player.hp);
243:   ui.staminaNum.textContent = Math.round(player.st);
244:   ui.hungerNum.textContent = Math.round(player.hunger);
245:   ui.status.textContent = player.hp <= 0 ? 'GONE' : player.hp < 30 ? 'CRITICAL' : player.hp < 60 ? 'HURT' : 'ALIVE';
246:   const d = world.safeDoor, wins = world.safeWindows;
247:   ui.doorPips.innerHTML = pips(d ? d.reinforced : 0);
248:   ui.windowPips.innerHTML = wins.map(w => pips(w.reinforced)).join('&nbsp;');
249:   const breached = (d && d.breached) || wins.some(w => w.breached);
250:   const secure = d && d.reinforced >= 3 && wins.every(w => w.reinforced >= 3);
251:   const partial = (d && d.reinforced > 0) || wins.some(w => w.reinforced > 0);
252:   ui.perimeter.textContent = breached ? 'BREACHED' : secure ? 'SECURE' : partial ? 'PARTIAL' : 'UNSECURED';
253:   ui.perimeter.style.color = breached ? '#e26951' : secure ? '#d6e675' : partial ? '#e2b566' : '#9aa493';
254:   document.body.classList.toggle('hurt', player.hp < 35 && player.hp > 0);
255:   ui.threat.classList.toggle('on', state.night && state.playing);
256:   if (state.night) ui.threat.innerHTML = breached ? '<i></i>THEY ARE INSIDE THE HOUSE' : '<i></i>THE DEAD ARE DRAWN TO NOISE';
257:   // objective copy
258:   if (state.playing) {
259:     if (state.night) {
260:       ui.goal.textContent = breached ? 'They are inside. Fight or flee.' : 'Hold the safehouse until dawn.';
261:     } else if (secure) {
262:       ui.goal.textContent = 'Perimeter secure. Hold until nightfall.';
263:     } else if (partial) {
264:       ui.goal.textContent = 'Finish boarding the safehouse.';
265:     } else {
266:       ui.goal.textContent = 'Scavenge the block. Board up before dark.';
267:     }
268:     const t = state.dayTime;
269:     if (!state.night) ui.timer.textContent = `NIGHTFALL IN ${fmtTime(Math.max(0, 150 - t))}`;
270:     else ui.timer.textContent = `DAWN IN ${fmtTime(Math.max(0, 390 - t))}`;
271:     ui.clock.textContent = clockString();
272:     ui.temp.textContent = Math.round(lerp(12, 7, state.nightFactor)) + '°C';
273:     ui.location.textContent = locationName();
274:   }
275: }
276: function fmtTime(s) {
277:   s = Math.max(0, Math.floor(s));
278:   return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
279: }
280: function clockString() {
281:   const t = state.dayTime;
282:   let mins;
283:   if (t < 150) mins = 16 * 60 + 42 + t * (138 / 150);
284:   else mins = 19 * 60 + (t - 150) * (600 / 240);
285:   const hh = Math.floor(mins / 60) % 24, mm = Math.floor(mins % 60);
286:   return `DAY 01 · ${String(hh).padStart(2, '0')}:${String(mm).padStart(2, '0')}`;
287: }
288: function locationName() {
289:   const x = player.gx, y = player.gy;
290:   if (x >= 6 && x <= 13 && y >= 25 && y <= 32) return 'WEST MERCER · SAFEHOUSE';
291:   if (x >= 2 && x <= 9 && y >= 2 && y <= 7) return 'WEST MERCER · HARDWARE';
292:   if (x >= 26 && x <= 33 && y >= 2 && y <= 8) return 'WEST MERCER · CORNER STORE';
293:   if (x >= 24 && x <= 32 && y >= 24 && y <= 31) return 'WEST MERCER · RANSACKED HOUSE';
294:   if (x >= 2 && x <= 5 && y >= 22 && y <= 26) return 'WEST MERCER · TOOL SHED';
295:   if (x >= 16 && x <= 19) return 'MERCER STREET · NORTH–SOUTH';
296:   if (y >= 16 && y <= 19) return 'MERCER STREET · CROSSROAD';
297:   return 'WEST MERCER · DEAD COUNTY';
298: }
