370: /* ---------------- interaction ---------------- */
371: let near = null;
372: function findNear() {
373:   const p = playerWorld();
374:   let best = null, bd = 2.7;
375:   for (const it of world.interactables) {
376:     if (it.kind === 'loot' && !it.active) continue;
377:     if (it.kind === 'car' && !it.active) continue;
378:     const d = Math.hypot(it.wx - p.x, it.wz - p.z);
379:     if (d < bd) { bd = d; best = it; }
380:   }
381:   near = best;
382:   return best;
383: }
384: function promptFor(it) {
385:   if (!it) return null;
386:   if (it.kind === 'loot') {
387:     return { primary: it.active ? 'SCAVENGE · ' + it.label.toUpperCase() : null, secondary: null };
388:   }
389:   if (it.kind === 'car') {
390:     if (!it.repaired) {
391:       const ok = (resources.scrap >= 3 && resources.parts >= 1);
392:       return { primary: ok ? 'REPAIR ENGINE · 3 SCRAP + 1 PART' : 'REPAIR ENGINE · NEED 3 SCRAP + 1 PART', secondary: null };
393:     }
394:     if (!it.fueled) {
395:       return { primary: resources.fuel >= 1 ? 'ADD FUEL · 1 FUEL' : 'ADD FUEL · NEED 1 FUEL', secondary: null };
396:     }
397:     return { primary: 'DRIVE OUT OF DEAD COUNTY', secondary: null };
398:   }
399:   // openings
400:   const o = it;
401:   if (o.reinforced > 0) {
402:     return {
403:       primary: `PRY A BOARD · ${o.reinforced}/3`,
404:       secondary: o.reinforced < 3 ? `BOARD UP · 1 PLANK (${resources.wood > 0 ? 'READY' : 'NONE'})` : null,
405:     };
406:   }
407:   if (o.breached || o.kind === 'broken') {
408:     return { primary: null, secondary: `BOARD UP THE OPENING · 1 PLANK (${resources.wood > 0 ? 'READY' : 'NONE'})` };
409:   }
410:   if (o.kind === 'door') {
411:     return { primary: o.open ? 'CLOSE DOOR' : 'OPEN DOOR', secondary: `BOARD UP · 1 PLANK (${resources.wood > 0 ? 'READY' : 'NONE'})` };
412:   }
413:   return { primary: null, secondary: `BOARD UP WINDOW · 1 PLANK (${resources.wood > 0 ? 'READY' : 'NONE'})` };
414: }
415: function updatePrompt() {
416:   if (!state.playing || state.modal) { ui.prompt.classList.remove('show'); ui.prompt2.classList.remove('show'); return; }
417:   const it = findNear();
418:   const p = promptFor(it);
419:   if (p?.primary) { ui.promptText.textContent = p.primary; ui.prompt.classList.add('show'); }
420:   else ui.prompt.classList.remove('show');
421:   if (p?.secondary) { ui.prompt2Text.textContent = p.secondary; ui.prompt2.classList.add('show'); }
422:   else ui.prompt2.classList.remove('show');
423: }
424: function interact() {
425:   if (!state.playing || state.modal) return;
426:   const it = findNear();
427:   if (!it) { toast('Nothing close enough to use.'); return; }
428:   if (it.kind === 'loot') { takeLoot(it); return; }
429:   if (it.kind === 'car') { useCar(it); return; }
430:   const o = it;
431:   if (o.reinforced > 0) {
432:     if (world.board(o, false)) {
433:       audio.hammer(); noisy(2);
434:       toast(o.reinforced === 0 ? 'Last board off. The opening is bare.' : `Board pried loose · ${o.reinforced}/3`);
435:       updateHud(); saveGame();
436:     }
437:     return;
438:   }
439:   if (o.kind === 'door') {
440:     if (o.breached) { toast('The frame is broken. Board it up with F.'); return; }
441:     o.open = !o.open; o.closed = !o.open;
442:     world.refreshOpening(o);
443:     audio.door(o.open);
444:     noisy(3);
445:     toast(o.open ? 'Door opened.' : 'Door closed.');
446:     saveGame();
447:     return;
448:   }
449:   if (o.kind === 'window') { toast(o.breached ? 'The glass is gone. Board it with F.' : 'Windows are fixed. Use F to board them.'); return; }
450:   toast('The opening is broken. Board it up with F.');
451: }
452: function boardUp() {
453:   if (!state.playing || state.modal) return;
454:   const it = findNear();
455:   if (!it) { toast('Nothing close enough to board.'); return; }
456:   if (it.kind !== 'door' && it.kind !== 'window' && it.kind !== 'broken') return;
457:   const o = it;
458:   if (o.reinforced >= 3) { toast('Already fully boarded. It is secure.'); return; }
459:   if ((resources.wood || 0) < 1) { toast('Need a plank to board this.', true); return; }
460:   resources.wood--;
461:   if (o.open && !o.breached) { o.open = false; o.closed = true; }
462:   world.board(o, true);
463:   audio.hammer(); noisy(5);
464:   toast(o.reinforced >= 3 ? 'Boarded tight. This opening is secure.' : `Boarded · ${o.reinforced}/3. Keep going.`);
465:   updateHud(); updateInventoryUI(); saveGame();
466: }
467: function takeLoot(it) {
468:   const room = INVENTORY_MAX - inventoryUsed();
469:   let taken = {}, remaining = {}, total = 0;
470:   for (const [k, v] of Object.entries(it.loot || {})) {
471:     const weight = ITEM[k]?.weight || 1;
472:     const available = Math.max(0, Math.floor(Number(v) || 0));
473:     const allowed = Math.max(0, Math.min(available, Math.floor((room + 1e-9) / weight)));
474:     if (allowed > 0) { resources[k] = (resources[k] || 0) + allowed; taken[k] = allowed; total += allowed; room -= allowed * weight; }
475:     if (allowed < available) remaining[k] = available - allowed;
476:   }
477:   it.loot = remaining;
478:   const summary = Object.entries(taken).map(([k, v]) => `+${v} ${ITEM[k].name}`).join(' · ');
479:   if (total > 0) {
480:     state.lootCount += total;
481:     audio.pickup(); noisy(3);
482:     toast(Object.keys(remaining).length ? `Partially scavenged · ${summary}` : `Scavenged · ${summary}`);
483:     if (!Object.keys(remaining).length) world.consumeLoot(it);
484:   } else {
485:     toast('Inventory full. Nothing picked up.', true);
486:   }
487:   updateInventoryUI(); updateHud(); saveGame();
488: }
489: function useCar(it) {
490:   if (!it.repaired) {
491:     if ((resources.scrap || 0) >= 3 && (resources.parts || 0) >= 1) {
492:       resources.scrap -= 3; resources.parts -= 1;
493:       it.repaired = true;
494:       world.setCarState({ repaired: true, fueled: it.fueled });
495:       toast('Engine turns over. It needs fuel to leave.');
496:       audio.craft(); noisy(12);
497:       updateInventoryUI(); updateHud(); saveGame();
498:     } else toast('Need 3 scrap and 1 part to repair the engine.', true);
499:     return;
500:   }
501:   if (!it.fueled) {
502:     if ((resources.fuel || 0) >= 1) {
503:       resources.fuel -= 1; it.fueled = true;
504:       world.setCarState({ repaired: true, fueled: true });
505:       toast('Tank filled. Press E again to drive out.');
506:       audio.pickup(); noisy(6);
507:       updateInventoryUI(); updateHud(); saveGame();
508:     } else toast('Engine runs. Find a can of fuel.', true);
509:     return;
510:   }
511:   endGame(true, 'escape');
512: }
