514: /* ---------------- combat ---------------- */
515: function nearestZombieInCone(range, cone) {
516:   const p = playerWorld();
517:   let best = null, bd = range;
518:   for (const z of zombies) {
519:     if (!z.alive) continue;
520:     const zw = worldOf(z.gx, z.gy);
521:     const d = Math.hypot(zw.x - p.x, zw.z - p.z);
522:     const ang = Math.atan2(zw.x - p.x, zw.z - p.z);
523:     if (d < bd && Math.abs(angleDiff(ang, player.aim)) < cone) { bd = d; best = z; }
524:   }
525:   return best;
526: }
527: function damageZombie(z, dmg) {
528:   if (!z.alive) return;
529:   z.hp -= dmg;
530:   z.hitT = .13;
531:   z.alert = 8;
532:   const zw = worldOf(z.gx, z.gy);
533:   world.addBlood(zw.x + (Math.random() - .5) * .4, zw.z + (Math.random() - .5) * .4, .65 + Math.random() * .35);
534:   for (const m of z.model.mats) { m.emissive.setHex(0x7a1d13); m.emissiveIntensity = .9; }
535:   if (z.hp <= 0) killZombie(z);
536:   else { audio.hit(); state.shake = Math.max(state.shake, .14); }
537: }
538: function killZombie(z) {
539:   z.alive = false; z.deadT = 0;
540:   state.kills++;
541:   const zw = worldOf(z.gx, z.gy);
542:   world.addBlood(zw.x, zw.z, 1.5 + Math.random() * .6);
543:   world.addBlood(zw.x + (Math.random() - .5) * 1.2, zw.z + (Math.random() - .5) * 1.2, .8);
544:   audio.gore();
545:   player.st = Math.min(100, player.st + 4);
546:   corpses.push(z);
547:   if (corpses.length > 14) {
548:     const old = corpses.shift();
549:     if (old && old.model) scene.remove(old.model.root);
550:   }
551: }
552: function hurt(n) {
553:   if (state.gameOver || state.mode !== 'play') return;
554:   player.hp = Math.max(0, player.hp - n);
555:   player.hurtT = .3;
556:   ui.hitflash.classList.add('on');
557:   setTimeout(() => ui.hitflash.classList.remove('on'), 130);
558:   state.shake = Math.max(state.shake, .38);
559:   audio.hurt();
560:   if (player.hp <= 0) endGame(false, 'death');
561:   else if (player.hp < 30 && performance.now() - state.lastHurt > 2200) { state.lastHurt = performance.now(); audio.heartbeat(); }
562: }
563: function attack() {
564:   if (!state.playing || state.modal || player.attackCd > 0) return;
565:   if (IS_TOUCH && !state.aimDrag) {
566:     // touch quality-of-life: snap to the closest ghoul
567:     const p = playerWorld();
568:     let best = null, bd = 5.5;
569:     for (const z of zombies) if (z.alive) {
570:       const d = Math.hypot(worldX(z.gx) - p.x, worldZ(z.gy) - p.z);
571:       if (d < bd) { bd = d; best = z; }
572:     }
573:     if (best) player.aim = Math.atan2(worldX(best.gx) - p.x, worldZ(best.gy) - p.z);
574:   }
575:   player.attackCd = weapon === 'bat' ? .78 : weapon === 'pistol' ? .5 : weapon === 'shiv' ? .42 : .46;
576:   player.attackT = .26;
577:   if (weapon === 'pistol') firePistol();
578:   else {
579:     audio.swing();
580:     const z = nearestZombieInCone(weapon === 'bat' ? 2.35 : 2.05, .95);
581:     if (z) {
582:       const dmg = weapon === 'bat' ? 86 : weapon === 'shiv' ? 50 : 26;
583:       damageZombie(z, dmg);
584:       const p = playerWorld(), zw = worldOf(z.gx, z.gy);
585:       const dx = zw.x - p.x, dz = zw.z - p.z, d = Math.hypot(dx, dz) || 1;
586:       moveActor(z, dx / d * .16, dz / d * .16, .3);
587:       state.shake = Math.max(state.shake, .16);
588:     }
589:     player.st = Math.max(0, player.st - (weapon === 'bat' ? 7 : 4));
590:   }
591: }
592: function firePistol() {
593:   if ((resources.ammo || 0) <= 0) { audio.empty(); toast('Click. Empty.', true, 1400); return; }
594:   resources.ammo--;
595:   updateInventoryUI();
596:   const p = playerWorld();
597:   const dirX = Math.sin(player.aim), dirZ = Math.cos(player.aim);
598:   const from = new THREE.Vector3(p.x + dirX * .55, 1.22, p.z + dirZ * .55);
599:   let bestZ = null, bestT = 26;
600:   for (const z of zombies) {
601:     if (!z.alive) continue;
602:     const zw = worldOf(z.gx, z.gy);
603:     const rx = zw.x - p.x, rz = zw.z - p.z;
604:     const t = rx * dirX + rz * dirZ;
605:     if (t < .4 || t > bestT) continue;
606:     const perp = Math.abs(rx * dirZ - rz * dirX);
607:     if (perp > .82) continue;
608:     if (!world.lineOfSight(p.x, p.z, zw.x, zw.z)) continue;
609:     bestT = t; bestZ = z;
610:   }
611:   const to = bestZ ? new THREE.Vector3(worldX(bestZ.gx), 1.05, worldZ(bestZ.gy)) : new THREE.Vector3(p.x + dirX * 22, 1.0, p.z + dirZ * 22);
612:   world.addTracer(from, to);
613:   world.flashMuzzle(from.x, from.y, from.z + .2);
614:   audio.shot();
615:   state.shake = Math.max(state.shake, .32);
616:   noisy(34);
