293:   /* ---------------- collision / vision ---------------- */
294:   function resolveCircle(x, z, r) {
295:     for (let pass = 0; pass < 2; pass++) {
296:       for (let i = 0; i < colliders.length; i++) {
297:         const c = colliders[i];
298:         if (!c.active) continue;
299:         if (c.shape === 'circle') {
300:           const dx = x - c.x, dz = z - c.z;
301:           const rr = r + c.r, d2 = dx * dx + dz * dz;
302:           if (d2 < rr * rr) {
303:             const d = Math.sqrt(d2) || .0001;
304:             x = c.x + dx / d * rr; z = c.z + dz / d * rr;
305:           }
306:         } else {
307:           const nx = clamp(x, c.x - c.hw, c.x + c.hw);
308:           const nz = clamp(z, c.z - c.hd, c.z + c.hd);
309:           const dx = x - nx, dz = z - nz, d2 = dx * dx + dz * dz;
310:           if (d2 < r * r) {
311:             if (d2 > 1e-8) {
312:               const d = Math.sqrt(d2);
313:               x = nx + dx / d * r; z = nz + dz / d * r;
314:             } else {
315:               // push out on the smallest axis
316:               const px = c.hw + r - Math.abs(x - c.x);
317:               const pz = c.hd + r - Math.abs(z - c.z);
318:               if (px < pz) x = c.x + Math.sign(x - c.x || 1) * (c.hw + r);
319:               else z = c.z + Math.sign(z - c.z || 1) * (c.hd + r);
320:             }
321:           }
322:         }
323:       }
324:     }
325:     return { x, z };
326:   }
