328:   function lineOfSight(x1, z1, x2, z2) {
329:     const gx1 = x1 / CELL + MAPW / 2, gy1 = z1 / CELL + MAPH / 2;
330:     const gx2 = x2 / CELL + MAPW / 2, gy2 = z2 / CELL + MAPH / 2;
331:     const d = Math.hypot(gx2 - gx1, gy2 - gy1);
332:     const steps = Math.ceil(d / .3);
333:     for (let i = 1; i < steps; i++) {
334:       const t = i / steps;
335:       if (blocksSight(Math.floor(gx1 + (gx2 - gx1) * t), Math.floor(gy1 + (gy2 - gy1) * t))) return false;
336:     }
337:     return true;
338:   }
