+  player.hunger = clamp(Number(p.hunger) || 100, 0, 100);
+  const safe = world.resolveCircle(worldX(player.gx), worldZ(player.gy), player.radius);
+  player.gx = gridX(safe.x); player.gy = gridZ(safe.z);
