+}
+if (joy) {
+  joy.addEventListener('pointerdown', e => {
+    e.preventDefault(); joyId = e.pointerId;
+    joy.setPointerCapture(e.pointerId); joyUpdate(e);
+  });
+  joy.addEventListener('pointermove', e => { if (e.pointerId === joyId) { e.preventDefault(); joyUpdate(e); } });
